#!/usr/bin/env python3
"""Embed our menu extension only; no proprietary game assets are included."""
from pathlib import Path
import json
root = Path(__file__).resolve().parents[1]
script = (root / 'src/native_menu/menu.js').read_text(encoding='utf-8')
schema = json.loads((root / 'src/settings_schema.json').read_text(encoding='utf-8'))
script = 'window.__controlFGSchema=' + json.dumps(schema, separators=(',', ':')) + ';\n' + script
assert ')CFGJS"' not in script
(root / 'src/native_menu/script.h').write_text(
    '// Generated by tools/embed-native-menu.py\n#pragma once\n'
    'static constexpr char kNativeMenuScript[] = R"CFGJS(' + script + ')CFGJS";\n', encoding='utf-8')
